CREATE TABLE IF NOT EXISTS pujans(id TEXT PRIMARY KEY,name_hi TEXT NOT NULL,description_hi TEXT NOT NULL DEFAULT '',price_inr INTEGER,advance_inr INTEGER,duration_minutes INTEGER,active BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),CHECK(price_inr IS NULL OR price_inr>=0),CHECK(advance_inr IS NULL OR advance_inr>=0));
CREATE TABLE IF NOT EXISTS products(id TEXT PRIMARY KEY,name_hi TEXT NOT NULL,description_hi TEXT NOT NULL DEFAULT '',price_inr INTEGER NOT NULL CHECK(price_inr>=0),active BOOLEAN NOT NULL DEFAULT TRUE,stock_quantity INTEGER,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS bookings(id BIGSERIAL PRIMARY KEY,public_id TEXT NOT NULL UNIQUE,customer_name TEXT NOT NULL,phone TEXT NOT NULL,pujan_id TEXT NOT NULL,pujan_name TEXT NOT NULL,requested_date DATE NOT NULL,requested_time TEXT NOT NULL,address TEXT NOT NULL,notes TEXT NOT NULL DEFAULT '',samagri_id TEXT,samagri_name TEXT,samagri_price_inr INTEGER NOT NULL DEFAULT 0 CHECK(samagri_price_inr>=0),pujan_price_inr INTEGER,advance_inr INTEGER,total_price_inr INTEGER,status TEXT NOT NULL DEFAULT 'pending_review' CHECK(status IN('pending_review','approved','rejected','completed','cancelled')),payment_status TEXT NOT NULL DEFAULT 'unpaid' CHECK(payment_status IN('unpaid','created','paid','refunded','failed')),payment_order_id TEXT,payment_id TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE INDEX IF NOT EXISTS bookings_date_status_idx ON bookings(requested_date,status);CREATE INDEX IF NOT EXISTS bookings_phone_idx ON bookings(phone);
CREATE TABLE IF NOT EXISTS samagri_orders(id BIGSERIAL PRIMARY KEY,public_id TEXT NOT NULL UNIQUE,customer_name TEXT NOT NULL,phone TEXT NOT NULL,delivery_address TEXT NOT NULL,items JSONB NOT NULL,subtotal_inr INTEGER NOT NULL CHECK(subtotal_inr>=0),shipping_inr INTEGER NOT NULL DEFAULT 0 CHECK(shipping_inr>=0),total_inr INTEGER NOT NULL CHECK(total_inr>=0),payment_status TEXT NOT NULL DEFAULT 'unpaid' CHECK(payment_status IN('unpaid','created','paid','refunded','failed')),payment_order_id TEXT,payment_id TEXT,status TEXT NOT NULL DEFAULT 'pending_review' CHECK(status IN('pending_review','approved','packed','shipped','delivered','cancelled')),created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS payment_events(id BIGSERIAL PRIMARY KEY,provider_event_id TEXT UNIQUE,event_type TEXT NOT NULL,payload JSONB NOT NULL DEFAULT '{}'::jsonb,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
INSERT INTO pujans(id,name_hi,description_hi,price_inr,advance_inr,duration_minutes) VALUES('satyanarayan','सत्यनारायण कथा','परिवार के मंगल एवं शुभ अवसरों हेतु',2100,500,120),('griha-pravesh','गृह प्रवेश पूजन','नवीन गृह में वैदिक मंगल प्रवेश',NULL,NULL,150),('rudrabhishek','रुद्राभिषेक','भगवान शिव का वैदिक अभिषेक',NULL,NULL,90),('mahamrityunjaya','महामृत्युंजय जाप','संकल्पानुसार वैदिक मंत्र-जाप',NULL,NULL,120),('other','अन्य पूजन','विशेष पूजन हेतु',NULL,NULL,NULL) ON CONFLICT(id) DO NOTHING;
INSERT INTO products(id,name_hi,description_hi,price_inr,stock_quantity) VALUES('thali','पूजन थाली','मूलभूत पूजन उपयोग हेतु',350,NULL),('kit','पूजन सामग्री किट','सामान्य पूजन की आवश्यक सामग्री',500,NULL),('havan','हवन सामग्री किट','हवन हेतु उपयोगी सामग्री',450,NULL) ON CONFLICT(id) DO NOTHING;